"""`ai serve` as a user service: launchd on macOS, systemd on Linux. The generated files never hold secrets."""
import os
from pathlib import Path
import plistlib
import shutil
import socket
import subprocess
import sys
import time

from .. import config as config_tool
from ..osutils import SAFE_PATH, REPO, private_file, resolve_bin
from ..tools import CLIS, TOOLS
from . import auth

LABEL = 'com.omni-ai.serve'
UNIT = 'omni-ai.service'
MARKER = 'Generated by the Omni AI service installer. Contains no secrets.'  # no double dash: it goes in an XML comment
PASSED_ENV = ('SMART_AI_HOME', 'SMART_AI_STATE', 'SMART_AI_LOG', 'SMART_AI_ACCOUNTS')
FATAL_EXIT = 2  # bad arguments: restarting cannot help
START_WAIT = 15


class ServiceError(Exception):
    pass


def run(*args):
    try:
        return subprocess.run(args, capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired) as error:
        return subprocess.CompletedProcess(args, 1, '', str(error))


def platform_name():
    return sys.platform


def service_file():
    if platform_name() == 'darwin':
        return Path.home() / 'Library/LaunchAgents' / f'{LABEL}.plist'
    return Path.home() / '.config/systemd/user' / UNIT


def log_dir():
    return Path(os.environ.get('SMART_AI_LOG', '~/.cache/smart-ai/usage.log')).expanduser().parent


def default_workdir():
    return Path.home() / '.local/share/smart-ai/serve'


def require_manager():
    """Stops early, with the reason, where there is no service manager to talk to."""
    name = platform_name()
    if name == 'darwin':
        if run('launchctl', 'print', _domain()).returncode != 0:
            raise ServiceError('Sem sessão do launchd para este usuário (acesso só por SSH?). Entre na sessão gráfica ou rode `ai serve` manualmente.')
    elif name.startswith('linux'):
        if not shutil.which('systemctl') or run('systemctl', '--user', 'show-environment').returncode != 0:
            raise ServiceError('systemd de usuário indisponível (container ou WSL sem systemd?). Rode `ai serve` manualmente. Em Docker, a política de reinício do Compose cuida disso.')
    else:
        raise ServiceError('Serviço não disponível neste sistema. Rode `ai serve` manualmente.')


def _domain():
    return f'gui/{os.getuid()}'


def command():
    """The absolute way to start the server, and any environment it needs to work."""
    found = resolve_bin('ai')
    if found:
        return [os.path.abspath(found), 'serve'], {}
    return [sys.executable, *SAFE_PATH, '-m', 'omni_ai', 'serve'], {'PYTHONPATH': str(REPO)}


def service_path():
    """Services do not read .zshrc or .bashrc: list every folder a tool was found in, then the system ones."""
    wanted = [resolve_bin(TOOLS[name].bin) for name in CLIS] + [resolve_bin('node'), resolve_bin('ai')]
    folders = [str(Path.home() / '.local/bin')] + [os.path.dirname(os.path.abspath(p)) for p in wanted if p]
    folders += ['/usr/local/bin', '/usr/bin', '/bin']
    return os.pathsep.join(dict.fromkeys(folders))


def environment(extra):
    env = {'PATH': service_path(), 'SMART_AI_SERVICE': '1', **extra}
    env.update({name: os.environ[name] for name in PASSED_ENV if os.environ.get(name)})
    return env


def server_args(args, workdir):
    argv = ['--host', args.host, '--port', str(args.port), '--max-concurrent', str(args.max_concurrent),
            '--timeout', str(args.timeout), '--mode', args.mode, '--workdir', str(workdir),
            *(('--queue-size', str(args.queue_size), '--queue-wait', str(args.queue_wait)) if hasattr(args, 'queue_size') else ()),
            '--log-file', str(log_dir() / 'serve.log')]
    if getattr(args, 'tool_emulation', False):
        argv.append('--tool-emulation')
    if getattr(args, 'enable_admin', False):
        argv.append('--enable-admin')
    if getattr(args, 'admin_allow_http', False):
        argv.append('--admin-allow-http')
    return argv


def _quote_systemd(text):
    return '"' + text.replace('\\', '\\\\').replace('"', '\\"').replace('%', '%%').replace('$', '$$') + '"'


def render_systemd(argv, env, workdir):
    out = log_dir() / 'serve.out.log'
    lines = [f'# {MARKER}', '[Unit]', 'Description=Omni AI CLI server', 'StartLimitIntervalSec=60', 'StartLimitBurst=5', '',
             '[Service]', 'ExecStart=' + ' '.join(_quote_systemd(a) for a in argv),
             'WorkingDirectory=' + str(workdir).replace('%', '%%')]
    lines += ['Environment=' + _quote_systemd(f'{k}={v}') for k, v in env.items()]
    lines += ['Restart=on-failure', 'RestartSec=5', f'RestartPreventExitStatus={FATAL_EXIT}', 'TimeoutStopSec=30',
              f'StandardOutput=append:{out}', f'StandardError=append:{out}', '', '[Install]', 'WantedBy=default.target', '']
    return '\n'.join(lines)


def render_launchd(argv, env, workdir):
    out = str(log_dir() / 'serve.out.log')
    data = plistlib.dumps({
        'Label': LABEL, 'ProgramArguments': argv, 'WorkingDirectory': str(workdir), 'EnvironmentVariables': env,
        'RunAtLoad': True, 'KeepAlive': {'SuccessfulExit': False}, 'ThrottleInterval': 5,
        'StandardOutPath': out, 'StandardErrorPath': out}).decode('utf-8')
    return data.replace('<plist ', f'<!-- {MARKER} -->\n<plist ', 1)


def render(argv, env, workdir):
    return (render_launchd if platform_name() == 'darwin' else render_systemd)(argv, env, workdir)


def _generated(path):
    try:
        return MARKER in path.read_text(encoding='utf-8')
    except (OSError, ValueError):
        return False


def start():
    path = service_file()
    if platform_name() == 'darwin':
        result = run('launchctl', 'bootstrap', _domain(), str(path))
    else:
        run('systemctl', '--user', 'daemon-reload')
        result = run('systemctl', '--user', 'enable', '--now', UNIT)
    if result.returncode != 0:
        raise ServiceError(f'O gerenciador recusou o serviço: {(result.stderr or result.stdout).strip()}')


def stop():
    if platform_name() == 'darwin':
        run('launchctl', 'bootout', f'{_domain()}/{LABEL}')
        _wait(lambda: not active(), 10)  # bootout returns early, and bootstrap fails while the old job is leaving
    else:
        run('systemctl', '--user', 'disable', '--now', UNIT)
        run('systemctl', '--user', 'daemon-reload')


def restart():
    if platform_name() == 'darwin':
        return run('launchctl', 'kickstart', '-k', f'{_domain()}/{LABEL}').returncode == 0
    return run('systemctl', '--user', 'restart', UNIT).returncode == 0


def active():
    if platform_name() == 'darwin':
        return run('launchctl', 'print', f'{_domain()}/{LABEL}').returncode == 0
    return run('systemctl', '--user', 'is-active', UNIT).stdout.strip() == 'active'


def _connect_host(host):
    return {'0.0.0.0': '127.0.0.1', '::': '::1'}.get(host, host)


def port_open(host, port):
    try:
        socket.create_connection((_connect_host(host), port), 1).close()
        return True
    except OSError:
        return False


def _wait(condition, seconds):
    deadline = time.monotonic() + seconds
    while time.monotonic() < deadline:
        if condition():
            return True
        time.sleep(0.2)
    return condition()


def warnings():
    """What will not work the same under the service. Names only, never values."""
    notes = []
    missing = [TOOLS[name].label for name in CLIS if not resolve_bin(TOOLS[name].bin)]
    if missing:
        notes.append('CLIs não encontrados: ' + ', '.join(missing))
    only_env = [p for p in config_tool.KEYS if (found := config_tool.stored_keys(p)) and all(o == 'env' for _, _, o in found)]
    if only_env:
        notes.append(f"Chaves só no ambiente, o serviço não as herda: {', '.join(only_env)}. Salve com `ai --key <ferramenta>`.")
    if platform_name().startswith('linux'):
        user = os.environ.get('USER') or Path.home().name
        if 'Linger=yes' not in run('loginctl', 'show-user', user, '-p', 'Linger').stdout:
            notes.append(f'Sem linger, o serviço só roda com sua sessão aberta. Para iniciar no boot: `loginctl enable-linger {user}`.')
    return notes


def install(args, loopback):
    """Returns the exit code. Success is only reported once the server answers on its port."""
    require_manager()
    if not args.port:
        raise ServiceError('O serviço precisa de uma porta fixa.')
    if args.mode == 'yolo' and not args.yes:
        raise ServiceError('--mode yolo deixa pedidos rodarem qualquer comando sem aprovação. Confirme com --yes.')
    # The service must not generate a key by itself: it would be printed to a log file. A key that only
    # exists in this shell's environment does not reach the service, so it does not count.
    created = None
    if not auth.stored():
        if not loopback:
            raise ServiceError('Host fora de 127.0.0.1 exige chave salva antes: `ai serve keys add NOME`.')
        created = auth.add('default')
    if getattr(args, 'enable_admin', False) and not auth.stored(auth.admin_keys_path()):
        raise ServiceError('--enable-admin exige uma chave salva antes: `ai serve admin-keys add NOME`.')
    path = service_file()
    existed = path.exists()
    if existed and not _generated(path) and not args.yes:
        raise ServiceError(f'{path} não foi gerado pelo Omni. Revise o arquivo; para sobrescrever, use --yes.')
    workdir = Path(args.workdir).expanduser().resolve() if args.workdir else default_workdir()
    workdir.mkdir(parents=True, exist_ok=True)
    log_dir().mkdir(parents=True, exist_ok=True)
    if existed:
        stop()
        _wait(lambda: not port_open(args.host, args.port), 10)
    if port_open(args.host, args.port):
        if existed:
            start()
        raise ServiceError(f'A porta {args.port} já está em uso.')
    argv, extra = command()
    temporary = path.with_suffix(path.suffix + '.tmp')
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary.write_text(render(argv + server_args(args, workdir), environment(extra), workdir), encoding='utf-8')
    os.replace(temporary, path)
    private_file(log_dir() / 'serve.out.log', 'w', encoding='utf-8', tighten=True).close()  # the manager appends and never rotates this one
    start()
    if not _wait(lambda: port_open(args.host, args.port), START_WAIT):
        stop()
        path.unlink(missing_ok=True)
        raise ServiceError(f'O servidor não respondeu na porta {args.port}. Veja {log_dir() / "serve.out.log"}')
    print(f'Serviço instalado: http://{args.host}:{args.port}/v1\nArquivo: {path}\nPasta de trabalho: {workdir}\nLogs: {log_dir()}/serve.log')
    if created:
        print(f'Chave de API criada (guarde agora, ela não será mostrada de novo):\n{created}')
    if args.mode != 'plan':
        print(f'Aviso: modo {args.mode}. Os pedidos alteram branches ou cópias de {workdir}, sem aprovação.', file=sys.stderr)
    for note in warnings():
        print(f'Aviso: {note}', file=sys.stderr)
    return 0


def uninstall(args):
    """Safe to repeat. Keeps config, keys, logins and logs, and linger, which other services may need."""
    path = service_file()
    if not path.exists():
        print('Serviço não instalado.')
        return 0
    if not _generated(path) and not args.yes:
        raise ServiceError(f'{path} não foi gerado pelo Omni. Para remover mesmo assim, use --yes.')
    require_manager()
    stop()
    path.unlink(missing_ok=True)
    print('Serviço removido. Configuração, chaves, logins e logs foram mantidos.')
    return 0


def _program(path):
    """The executable the service file points at, or None when it cannot be read."""
    try:
        if platform_name() == 'darwin':
            return plistlib.loads(path.read_bytes())['ProgramArguments'][0]
        line = next(l for l in path.read_text(encoding='utf-8').splitlines() if l.startswith('ExecStart='))
        return line.split('"')[1]
    except (OSError, ValueError, KeyError, IndexError, StopIteration, plistlib.InvalidFileException):
        return None


def describe():
    """None when not installed, else (is running, problem or None, service file)."""
    if platform_name() not in ('darwin',) and not platform_name().startswith('linux'):
        return None
    path = service_file()
    if not path.exists():
        return None
    program = _program(path)
    problem = None
    if program and not os.path.exists(program):
        problem = f'aponta para {program}, que não existe mais. Reinstale com `ai serve --install-service`.'
    return active(), problem, path


def status():
    info = describe()
    if not info:
        print('Serviço não instalado.')
        return 1
    running, problem, path = info
    print(f"Serviço: {'rodando' if running else 'parado'}\nArquivo: {path}\nLogs: {log_dir()}/serve.log e serve.out.log")
    if problem:
        print(f'Problema: {problem}', file=sys.stderr)
    return 0 if running and not problem else 1


def after_update():
    """A running service keeps the old code until restarted."""
    info = describe()
    if not info or not info[0]:
        return None
    return restart()
